-- T0B-13.C18 schema suite: migration_staging catalogue properties (C18 05-SCHEMA §1, §2, §3, §4, §5, §6; §12 tests 2, 8, 11 in catalogue form; AC-0B-2.1, 2.2, 2.3, 2.4, 3.1, 3.2, 3.3, 3.4, 3.5, 3.6, 3.7, 4.1, 4.2, 4.3, 5.1, 5.2, 5.3, 6.1, 6.2, 6.3, 6.4).
-- Pure pg_catalog assertions: no fixtures, no data written. One rolled-back transaction. RLS is never disabled.
-- Run from the repo root: pg_prove -d <db> db/tests/migration_staging/T0B-13.C18_schema.test.sql   (pgTAP in schema `extensions`; migrations loaded; superuser). NOT run in the unit-test environment (no database).
-- Needs the role lims_migration (db/bootstrap, C18 05-SCHEMA §2, CR-C18-001): without it the migrations do not apply (LD-202 (a): blocking CR).
-- Markers (the node test checks them): C18 check 1 inventory / owner / roles, 2 RLS ENABLE+FORCE, 3 policy set (P-16 guard, run-state purge DELETE), 4 grants (table, schema, EXECUTE), 5 indexes / constraints / FKs / mandatory columns,
-- 6 triggers + functions + audit exclusion (§1.5), 7 DEFINER inventory + FK direction (AC-0B-6.1 / 6.2 / 6.3), 8 views (none) + seeds (none) (AC-0B-6.4). The 11 §12 behaviour tests T1..T11 live in T0B-13.C18_behaviour.test.sql.
-- ACs: AC-0B-2.1 AC-0B-2.2 AC-0B-2.3 AC-0B-2.4 AC-0B-3.1 AC-0B-3.2 AC-0B-3.3 AC-0B-3.4 AC-0B-3.5 AC-0B-3.6 AC-0B-3.7 AC-0B-4.1 AC-0B-4.2 AC-0B-4.3 AC-0B-5.1 AC-0B-5.2 AC-0B-5.3 AC-0B-6.1 AC-0B-6.2 AC-0B-6.3 AC-0B-6.4
-- (2.x RLS/policies: checks 2-3; 3.x tenant isolation structure: checks 2, 5 + generated probes + behaviour T1/T9; 4.x grants/immutability: checks 4, 6; 5.x audit: check 6; 6.x order/FK/owner/views: checks 1, 7, 8)
BEGIN;
SET search_path = extensions, public, pg_catalog;
SELECT * FROM no_plan();

-- t: table; cls: §3 class; u: lims_migration UPDATE; d: lims_migration DELETE; aud: audit trigger (§1.5 / §4: runs, run_files, crosswalk_entries, batches); n: number of mandatory columns of the class present (E has no expires_at, §1.6)
CREATE TEMP TABLE rt(t, cls, u, d, aud, mand) AS VALUES
  ('runs','M',true,false,true,8),('run_events','A',false,false,false,4),('run_files','M',true,false,true,8),('crosswalk_entries','M',true,false,true,8),('batches','M',true,false,true,8),('reports','A',false,false,false,4),('signoffs','A',false,false,false,4),
  ('stg_patients','E',true,true,false,3),('stg_visits','E',true,true,false,3),('stg_results','E',true,true,false,3),('stg_documents','E',true,true,false,3),('stg_financial','E',true,true,false,3),('stg_masters','E',true,true,false,3),
  ('match_pairs','E',true,true,false,3),('issues','E',false,true,false,3),('samples','E',true,true,false,3);

-- C18 check 1: inventory, owner (AC-0B-1.2, AC-0B-6.3), schema privileges (§1.1, §2 CI assertions), role attributes, no sequences / enums / views
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'migration_staging'::regnamespace AND c.relkind IN ('r','p')), 16, 'C18 check 1: migration_staging holds exactly the 16 chunk tables (05-SCHEMA §4 count of table statements; no event_inbox, §1.9)');
SELECT is((SELECT array_agg(relname::text ORDER BY relname) FROM pg_class WHERE relnamespace = 'migration_staging'::regnamespace AND relkind IN ('r','p')), (SELECT array_agg(t ORDER BY t) FROM rt), 'C18 check 1: the table set equals the §3 inventory');
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'migration_staging'::regnamespace AND c.relkind IN ('v','m')), 0, 'C18 check 1 / AC-0B-6.4: no view, no materialized view (§10)');
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'migration_staging'::regnamespace AND c.relkind = 'S'), 0, 'C18 check 1: no sequences');
SELECT is((SELECT count(*)::int FROM pg_type t WHERE t.typnamespace = 'migration_staging'::regnamespace AND t.typtype = 'e'), 0, 'C18 check 1: no ENUM types');
SELECT is(pg_get_userbyid(c.relowner), 'lims_owner', 'C18 check 1: migration_staging.' || c.relname || ' owned by lims_owner (AC-0B-1.2, AC-0B-6.3)') FROM pg_class c WHERE c.relnamespace = 'migration_staging'::regnamespace AND c.relkind IN ('r','p');
SELECT is(has_schema_privilege('lims_migration', 'migration_staging', 'USAGE'), true, 'C18 check 1 / §2: lims_migration has USAGE on schema migration_staging');
SELECT is(has_schema_privilege(r, 'migration_staging', 'USAGE'), false, 'C18 check 1 / §1.1: ' || r || ' has NO USAGE on schema migration_staging') FROM unnest(ARRAY['lims_app','lims_api','lims_worker','lims_analytics','anon','authenticated']) r;
SELECT is(has_schema_privilege(r, 'migration_staging', 'CREATE'), false, 'C18 check 1: ' || r || ' cannot CREATE in migration_staging') FROM unnest(ARRAY['lims_migration','lims_app','lims_api','lims_worker','lims_analytics']) r;
SELECT is((SELECT rolbypassrls OR rolsuper OR rolcreaterole OR rolcreatedb OR rolreplication FROM pg_roles WHERE rolname = 'lims_migration'), false, 'C18 check 1 / §2 CI: lims_migration has no BYPASSRLS / SUPERUSER / CREATEROLE / CREATEDB / REPLICATION');
SELECT is((SELECT rolcanlogin FROM pg_roles WHERE rolname = 'lims_migration'), false, 'C18 check 1 / §2 CI: rolcanlogin = false in the committed bootstrap state (migration-window.yml toggles it)');
SELECT is((SELECT count(*)::int FROM pg_shdepend d JOIN pg_roles r ON r.oid = d.refobjid WHERE r.rolname = 'lims_migration' AND d.deptype = 'o'), 0, 'C18 check 1 / §2 CI: lims_migration owns no object');
-- STALE fix T0B-GREEN-2: LD-226 / CR-C18-001 (db/bootstrap/00_roles.sql): lims_migration is created NOLOGIN with NO lims_app membership; the D-136 PROPOSED EXCEPTION (GRANT lims_app TO lims_migration WITH INHERIT TRUE, SET FALSE) stays undecided.
-- The two assertions keep the property they named (the loader role is never an owner / queue role) and now pin the decided state; they go red when D-136 is accepted and the grant is added (then restore the old expectation).
SELECT is((SELECT count(*)::int FROM pg_auth_members m JOIN pg_roles r ON r.oid = m.member WHERE r.rolname = 'lims_migration'), 0, 'C18 check 1 / §2 CI / LD-226: lims_migration is a member of no role (in particular not lims_owner, not lims_queue, not lims_app: D-136 undecided)');
SELECT is(pg_has_role('lims_migration', r, 'MEMBER'), false, 'C18 check 1 / §2 / LD-226: lims_migration has no GRANT of ' || r || ' (no INHERIT / SET path to owner or request grants)') FROM unnest(ARRAY['lims_app','lims_owner','lims_queue']) r;
SELECT is((SELECT rolconfig FROM pg_roles WHERE rolname = 'lims_migration') @> ARRAY['search_path=""'], true, 'C18 check 1 / §2: ALTER ROLE lims_migration SET search_path = empty');

-- C18 check 2: RLS ENABLE + FORCE on all 16 tables, none exempt (AC-0B-2.1, 2.4)
SELECT is((SELECT relrowsecurity AND relforcerowsecurity FROM pg_class WHERE oid = ('migration_staging.' || t)::regclass), true, 'C18 check 2 / AC-0B-2.1: ENABLE + FORCE RLS on migration_staging.' || t) FROM rt;
SELECT is(NOT EXISTS (SELECT 1 FROM pg_class WHERE relnamespace = 'migration_staging'::regnamespace AND relkind = 'r' AND NOT (relrowsecurity AND relforcerowsecurity)), true, 'C18 check 2 / AC-0B-2.4: every migration_staging table has ENABLE + FORCE RLS');
SELECT is((SELECT count(*)::int FROM information_schema.columns WHERE table_schema = 'migration_staging' AND column_name = 'tenant_id' AND is_nullable = 'YES'), 0, 'C18 check 2 / AC-0B-3.5: tenant_id is NOT NULL everywhere');
SELECT is((SELECT count(*)::int FROM information_schema.columns WHERE table_schema = 'migration_staging' AND column_name = 'tenant_id' AND column_default IS NOT NULL), 0, 'C18 check 2 / §1.1: tenant_id has no default');
SELECT is((SELECT count(*)::int FROM information_schema.columns WHERE table_schema = 'migration_staging' AND column_name = 'id' AND column_default IS NOT NULL), 0, 'C18 check 2 / §1.3: id has no default (UUIDv7 from application code)');

-- C18 check 3: policies (AC-0B-2.3): 53 policies, all TO lims_migration only, P-16 guard everywhere, purge DELETE bound to the run state
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'migration_staging'), 53, 'C18 check 3 / §5: 53 policies (16 select + 16 insert + 12 update + 8 purge delete + issues delete)');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'migration_staging' AND roles <> ARRAY['lims_migration']::name[]), 0, 'C18 check 3 / §1.2 (PROPOSED EXCEPTION D-136): every policy is TO lims_migration only (never lims_app / PUBLIC)');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'migration_staging' AND tablename = rt.t AND cmd = 'SELECT'), 1, 'C18 check 3: one SELECT policy on migration_staging.' || t) FROM rt;
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'migration_staging' AND tablename = rt.t AND cmd = 'INSERT'), 1, 'C18 check 3: one INSERT policy on migration_staging.' || t) FROM rt;
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'migration_staging' AND tablename = rt.t AND cmd = 'UPDATE'), CASE WHEN u THEN 1 ELSE 0 END, 'C18 check 3 / §5 (b): UPDATE policy on migration_staging.' || t || ' iff lims_migration has UPDATE (not run_events / reports / signoffs / issues)') FROM rt;
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'migration_staging' AND tablename = rt.t AND cmd = 'DELETE'), CASE WHEN d THEN 1 ELSE 0 END, 'C18 check 3 / §5 (c)(d): DELETE policy on migration_staging.' || t || ' iff lims_migration has DELETE (class E tables only)') FROM rt;
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'migration_staging' AND NOT (coalesce(qual, '') || coalesce(with_check, '')) LIKE '%current_tenant_id%'), 0, 'C18 check 3: tenant predicate in every policy');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'migration_staging' AND ((qual IS NOT NULL AND qual NOT LIKE '%is_staff_or_system%') OR (with_check IS NOT NULL AND with_check NOT LIKE '%is_staff_or_system%'))), 0, 'C18 check 3 / 08 A17 P-16: every USING and every WITH CHECK carries app.is_staff_or_system()');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'migration_staging' AND (coalesce(qual, '') || coalesce(with_check, '')) ~ 'current_centre_ids|has_all_centres'), 0, 'C18 check 3 / §5: no centre-scoped policy (staging rows carry centre_id only as a derived crosswalk value)');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'migration_staging' AND (coalesce(qual, '') || coalesce(with_check, '')) ~ '(^|[ (])true($|[ )])'), 0, 'C18 check 3 / REQ-SEC-016: no USING (true)');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'migration_staging' AND policyname !~ ('^' || tablename || '__(select|insert|update|delete)__tenant$')), 0, 'C18 check 3: policy names are <table>__<cmd>__tenant');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'migration_staging' AND policyname !~ ('__' || lower(cmd) || '__')), 0, 'C18 check 3: the command in the policy name matches the policy command');
SELECT matches((SELECT qual FROM pg_policies WHERE schemaname = 'migration_staging' AND tablename = rt.t AND cmd = 'DELETE' AND rt.t <> 'issues'), 'signed_off.*voided.*voided_partial.*abandoned', 'C18 check 3 / §5 (c): migration_staging.' || t || ' DELETE only for a run that is signed_off / voided / voided_partial / abandoned') FROM rt WHERE d AND t <> 'issues';
SELECT matches((SELECT qual FROM pg_policies WHERE schemaname = 'migration_staging' AND tablename = rt.t AND cmd = 'DELETE'), 'purge_not_before.*early_purge_approval', 'C18 check 3 / §5 (c): migration_staging.' || t || ' DELETE honours purge_not_before or an early_purge_approval signoff') FROM rt WHERE d AND t <> 'issues';
SELECT is((SELECT qual NOT LIKE '%purge_not_before%' AND qual NOT LIKE '%migration_staging.runs%' FROM pg_policies WHERE schemaname = 'migration_staging' AND policyname = 'issues__delete__tenant'), true, 'C18 check 3 / §5 (d): issues DELETE has no run-state condition');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'migration_staging' AND cmd NOT IN ('SELECT','INSERT','UPDATE','DELETE')), 0, 'C18 check 3: no FOR ALL policy');

-- C18 check 4: grant matrix (AC-0B-4.2 / 4.3; §2, §4 grant lines): lims_migration only; nothing for any other role
SELECT is(ARRAY[has_table_privilege('lims_migration', 'migration_staging.' || t, 'SELECT'), has_table_privilege('lims_migration', 'migration_staging.' || t, 'INSERT'), has_table_privilege('lims_migration', 'migration_staging.' || t, 'UPDATE'), has_table_privilege('lims_migration', 'migration_staging.' || t, 'DELETE')],
  ARRAY[true, true, u, d], 'C18 check 4 / AC-0B-4.1 / 4.2: lims_migration privileges on migration_staging.' || t || ' = §4 (S I' || CASE WHEN u THEN ' U' ELSE '' END || CASE WHEN d THEN ' D' ELSE '' END || ')') FROM rt;
SELECT is(has_table_privilege('lims_migration', 'migration_staging.' || t, 'TRUNCATE') OR has_table_privilege('lims_migration', 'migration_staging.' || t, 'REFERENCES') OR has_table_privilege('lims_migration', 'migration_staging.' || t, 'TRIGGER'), false, 'C18 check 4: no TRUNCATE / REFERENCES / TRIGGER on migration_staging.' || t) FROM rt;
SELECT is(has_table_privilege(r, 'migration_staging.' || x.t, p), false, 'C18 check 4 / §12.2: ' || r || ' has no ' || p || ' on migration_staging.' || x.t) FROM rt x, unnest(ARRAY['lims_api','lims_worker','lims_app','lims_analytics','anon','authenticated']) r, unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE']) p;
SELECT is((SELECT count(*)::int FROM information_schema.role_table_grants WHERE table_schema = 'migration_staging' AND grantee NOT IN ('lims_migration','lims_owner')), 0, 'C18 check 4: nothing granted to any role but lims_migration (and the owner)');
SELECT is((SELECT count(*)::int FROM information_schema.column_privileges WHERE table_schema = 'migration_staging' AND grantee NOT IN ('lims_migration','lims_owner')), 0, 'C18 check 4: no column grant to any other role');
SELECT is(has_function_privilege('lims_migration', 'app.core_resolve_tenant_code(text)', 'EXECUTE'), true, 'C18 check 4 / §2 / D-134: lims_migration may EXECUTE app.core_resolve_tenant_code(text)');
SELECT is(has_function_privilege('lims_migration', 'app.cron_tenant_ids()', 'EXECUTE'), true, 'C18 check 4 / §2 / A13 P-6: lims_migration may EXECUTE app.cron_tenant_ids()');
SELECT is((SELECT array_agg(p.proname::text ORDER BY p.proname::text) FROM pg_proc p WHERE p.prosecdef AND has_function_privilege('lims_migration', p.oid, 'EXECUTE') AND NOT has_function_privilege('lims_app', p.oid, 'EXECUTE')), ARRAY['core_resolve_tenant_code','cron_tenant_ids'], 'C18 check 4 / §12.11: lims_migration can EXECUTE no DEFINER beyond the two it was granted (what it inherits from lims_app aside)');

-- C18 check 5: indexes and constraints (§4): tenant_id leads every index; __p_ partial; UNIQUE (tenant_id, id) and the tenant FK everywhere; FKs only into migration_staging / core.tenants / core.collection_centres; mandatory columns (class E without expires_at, §1.6)
SELECT is((regexp_match(pg_get_indexdef(i.indexrelid), '\(([^,)]+)'))[1], 'tenant_id', 'C18 check 5: index ' || c.relname || ' leads with tenant_id')
  FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_class t ON t.oid = i.indrelid
  WHERE t.relnamespace = 'migration_staging'::regnamespace AND NOT i.indisprimary;
SELECT is((SELECT count(*)::int FROM pg_indexes WHERE schemaname = 'migration_staging' AND indexname ~ '__p_(uq|idx)$' AND indexdef NOT LIKE '% WHERE %'), 0, 'C18 check 5: every __p_ index is partial');
SELECT is((SELECT count(*)::int FROM pg_indexes WHERE schemaname = 'migration_staging' AND indexname NOT IN (SELECT conname FROM pg_constraint WHERE connamespace = 'migration_staging'::regnamespace)), 30, 'C18 check 5: exactly the 30 spec indexes beyond the constraint-backed ones (no extra index)');
SELECT is((SELECT indexdef FROM pg_indexes WHERE schemaname = 'migration_staging' AND indexname = 'runs__tenant_id_active_writer__p_uq'), 'CREATE UNIQUE INDEX runs__tenant_id_active_writer__p_uq ON migration_staging.runs USING btree (tenant_id) WHERE (status = ANY (ARRAY[''loading''::text, ''voiding''::text]))', 'C18 check 5 / §12.7: one writing run per tenant (03-APP-FLOW E2)');
SELECT is((SELECT count(*)::int FROM pg_constraint WHERE conrelid = ('migration_staging.' || t)::regclass AND contype = 'u' AND pg_get_constraintdef(oid) = 'UNIQUE (tenant_id, id)'), 1, 'C18 check 5 / 04 D8: UNIQUE (tenant_id, id) on migration_staging.' || t) FROM rt;
SELECT is((SELECT count(*)::int FROM pg_constraint WHERE conrelid = ('migration_staging.' || t)::regclass AND contype = 'f' AND confrelid = 'core.tenants'::regclass AND pg_get_constraintdef(oid) = 'FOREIGN KEY (tenant_id) REFERENCES core.tenants(id)'), 1, 'C18 check 5 / C0 §9 rule 1: tenant FK -> core.tenants on migration_staging.' || t) FROM rt;
SELECT is((SELECT count(*)::int FROM pg_constraint c WHERE c.contype = 'f' AND c.conrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'migration_staging'::regnamespace)
  AND cardinality(c.conkey) = 1 AND c.confrelid <> 'core.tenants'::regclass), 0, 'C18 check 5: every FK except the tenant FK is composite (tenant_id, x) (02-CV §5.4)');
SELECT is((SELECT array_agg(DISTINCT c.confrelid::regclass::text ORDER BY c.confrelid::regclass::text) FROM pg_constraint c WHERE c.contype = 'f' AND c.conrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'migration_staging'::regnamespace) AND c.confrelid::regclass::text NOT LIKE 'migration_staging.%'), ARRAY['core.collection_centres','core.tenants'], 'C18 check 5 / §1.8: the only FKs out of the schema go to core.tenants and core.collection_centres');
SELECT is((SELECT count(*)::int FROM pg_attribute WHERE attrelid = 'migration_staging.stg_patients'::regclass AND attname IN ('target_patient_id') AND NOT attisdropped) - (SELECT count(*)::int FROM pg_constraint WHERE conrelid = 'migration_staging.stg_patients'::regclass AND contype = 'f' AND conkey @> ARRAY[(SELECT attnum FROM pg_attribute WHERE attrelid = 'migration_staging.stg_patients'::regclass AND attname = 'target_patient_id')]), 1, 'C18 check 5 / §1.8: target ids (target_patient_id ...) are plain uuid without FK');
SELECT is((SELECT count(*)::int FROM pg_constraint WHERE conrelid IN ('migration_staging.match_pairs'::regclass, 'migration_staging.samples'::regclass) AND contype = 'f' AND confrelid = 'migration_staging.stg_patients'::regclass AND confdeltype = 'c'), 3, 'C18 check 5 / §4: match_pairs a / b and samples patient FKs are ON DELETE CASCADE (purge deletes stg_patients first)');
SELECT is((SELECT count(*)::int FROM pg_attribute a WHERE a.attrelid = ('migration_staging.' || t)::regclass AND a.attnum > 0 AND NOT a.attisdropped AND a.attname = ANY (
    CASE cls WHEN 'M' THEN ARRAY['id','tenant_id','created_at','created_by','updated_at','updated_by','version','is_active'] WHEN 'A' THEN ARRAY['id','tenant_id','created_at','created_by'] ELSE ARRAY['id','tenant_id','created_at'] END)),
  mand, 'C18 check 5 / §1.6 P-18(b): migration_staging.' || t || ' carries every class-' || cls || ' mandatory column (class E: all but expires_at)') FROM rt;
SELECT is((SELECT count(*)::int FROM pg_attribute WHERE attrelid = ('migration_staging.' || t)::regclass AND attname = 'expires_at' AND NOT attisdropped), 0, 'C18 check 5 / §1.6: migration_staging.' || t || ' has no expires_at (expiry per run: runs.purge_not_before)') FROM rt WHERE cls = 'E';
SELECT is((SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid = 'migration_staging.match_pairs'::regclass AND conname = 'match_pairs__decision__ck') ~ 'lab_form_reference IS NOT NULL', true, 'C18 check 5 / D-133: a decided match pair needs lab_form_reference (CHECK)');
SELECT is((SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid = 'migration_staging.match_pairs'::regclass AND conname = 'match_pairs__form_ref__ck'), 'CHECK (((lab_form_reference IS NULL) OR ((char_length(lab_form_reference) >= 1) AND (char_length(lab_form_reference) <= 120))))', 'C18 check 5: match_pairs__form_ref__ck added by ALTER TABLE (§4)');

-- C18 check 6: triggers, functions, audit (AC-0B-4.1, 5.1, 5.2, 5.3; §1.5): 3 mutable-column triggers + the runs lifecycle guard; audit on runs, run_files, crosswalk_entries, batches ONLY (no row audit on stg_*, match_pairs, issues, samples)
SELECT is((SELECT count(*)::int FROM pg_trigger tg WHERE tg.tgrelid = ('migration_staging.' || t)::regclass AND NOT tg.tgisinternal AND tg.tgname = t || '__audit' AND tg.tgfoid = 'app.tg_row_audit'::regproc), CASE WHEN aud THEN 1 ELSE 0 END, 'C18 check 6 / AC-0B-5.1: audit trigger on migration_staging.' || t || ' iff §4 closing comment (runs, run_files, crosswalk_entries, batches)') FROM rt WHERE t <> 'signoffs';
SELECT is((SELECT count(*)::int FROM pg_trigger tg WHERE tg.tgrelid = ('migration_staging.' || t)::regclass AND NOT tg.tgisinternal AND tg.tgfoid = 'app.tg_row_audit'::regproc), 0, 'C18 check 6 / AC-0B-5.3 / §1.5 / §12.8: NO row-audit trigger on migration_staging.' || t || ' (staging copy of the package; PROPOSED EXCEPTION)') FROM rt WHERE cls = 'E';
SELECT is((SELECT count(*)::int FROM pg_trigger tg WHERE tg.tgrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'migration_staging'::regnamespace) AND NOT tg.tgisinternal AND tg.tgfoid = 'app.tg_row_audit'::regproc AND tg.tgrelid NOT IN ('migration_staging.signoffs'::regclass)), 4, 'C18 check 6 / AC-0B-5.2: 4 audit triggers (runs, run_files, crosswalk_entries, batches)');
SELECT is((SELECT array_agg(tgname::text ORDER BY tgname::text) FROM pg_trigger WHERE tgrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'migration_staging'::regnamespace) AND NOT tgisinternal AND tgname LIKE '%\_\_mutable\_columns'),
  ARRAY['batches__mutable_columns','run_files__mutable_columns','runs__mutable_columns'], 'C18 check 6 / AC-0B-4.1: the 3 spec immutability triggers (permanent tables runs, batches, run_files)');
SELECT is((SELECT tgfoid::regproc::text FROM pg_trigger WHERE tgrelid = ('migration_staging.' || t)::regclass AND tgname = t || '__mutable_columns'), 'app.enforce_mutable_columns', 'C18 check 6: migration_staging.' || t || ' uses the C0 immutability trigger') FROM unnest(ARRAY['runs','batches','run_files']) t;
SELECT is((SELECT count(*)::int FROM pg_trigger tg WHERE tg.tgrelid = 'migration_staging.runs'::regclass AND NOT tg.tgisinternal AND tg.tgname NOT LIKE '%\_\_audit' AND tg.tgname NOT LIKE '%\_\_mutable\_columns' AND tg.tgfoid = 'migration_staging.runs_lifecycle_guard'::regproc AND (tg.tgtype & 2) = 2 AND (tg.tgtype & 16) = 16 AND (tg.tgtype & 1) = 1), 1, 'C18 check 6 / §12.5: runs has its lifecycle trigger (BEFORE UPDATE FOR EACH ROW -> runs_lifecycle_guard())');
SELECT is((SELECT prosecdef FROM pg_proc WHERE oid = 'migration_staging.runs_lifecycle_guard'::regproc), false, 'C18 check 6 / 04 D7: migration_staging.runs_lifecycle_guard is SECURITY INVOKER');
SELECT is((SELECT proconfig FROM pg_proc WHERE oid = 'migration_staging.runs_lifecycle_guard'::regproc), ARRAY['search_path=""'], 'C18 check 6: runs_lifecycle_guard has search_path = empty');
SELECT is((SELECT count(*)::int FROM pg_trigger WHERE tgrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'migration_staging'::regnamespace) AND NOT tgisinternal AND tgname NOT LIKE '%\_\_audit'), 4, 'C18 check 6: 3 mutable-column triggers + 1 lifecycle guard, nothing else');
SELECT is((SELECT count(*)::int FROM pg_proc WHERE pronamespace = 'migration_staging'::regnamespace), 1, 'C18 check 6: migration_staging holds exactly one function (runs_lifecycle_guard)');
SELECT is((SELECT count(*)::int FROM pg_proc WHERE pronamespace = 'migration_staging'::regnamespace AND prosecdef), 0, 'C18 check 6: no SECURITY DEFINER function in schema migration_staging');

-- C18 check 7: DEFINER inventory, FK direction (AC-0B-6.1 / 6.2 / 6.3; REQ-SEC-031, REQ-SEC-020)
SELECT is((SELECT count(*)::int FROM pg_proc WHERE prosecdef AND (pronamespace = 'migration_staging'::regnamespace OR proname LIKE 'migration\_staging%')), 0, 'C18 check 7 / AC-0B-6.3: the chunk has no DEFINER function (no inventory row)');
SELECT is((SELECT array_agg(DISTINCT n.nspname::text ORDER BY n.nspname::text) FROM pg_constraint c JOIN pg_class r ON r.oid = c.confrelid JOIN pg_namespace n ON n.oid = r.relnamespace WHERE c.contype = 'f' AND c.conrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'migration_staging'::regnamespace)),
  ARRAY['core','migration_staging'], 'C18 check 7 / AC-0B-6.2: migration_staging FKs point into migration_staging and core only (01 §5 R3)');
SELECT is((SELECT count(*)::int FROM pg_constraint c JOIN pg_class r ON r.oid = c.confrelid WHERE c.contype = 'f' AND r.relnamespace = 'migration_staging'::regnamespace AND c.conrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace = 'migration_staging'::regnamespace)), 0, 'C18 check 7 / AC-0B-6.2: nothing references migration_staging from another schema');
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'migration_staging'::regnamespace AND c.relkind = 'r' AND c.relname IN (SELECT t FROM rt)), 16, 'C18 check 7 / AC-0B-6.1: all 16 tables exist after the migrations applied in order on an empty database');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'storage' AND policyname LIKE 'migration_staging%'), 0, 'C18 check 7: no storage policy is created by SQL');

-- C18 check 8: views (AC-0B-6.4; §10: none) and seeds (§11: none in production)
SELECT is((SELECT count(*)::int FROM pg_class WHERE relnamespace = 'migration_staging'::regnamespace AND relname LIKE 'v\_pub\_%'), 0, 'C18 check 8 / AC-0B-6.4: no v_pub_* view (the view column contract is vacuous: IC §6 lists none for migration_staging)');
SELECT is((SELECT count(*)::int FROM migration_staging.runs) + (SELECT count(*)::int FROM migration_staging.crosswalk_entries) + (SELECT count(*)::int FROM migration_staging.stg_patients) + (SELECT count(*)::int FROM migration_staging.signoffs), 0, 'C18 check 8 / §11: no rows seeded by the migrations');

SELECT * FROM finish();
ROLLBACK;
